/* ACT IV (part 2) — The Amber Wastes, the Saltwind Coast, Frostmere */
(function(){
const G = globalThis.G, sc = G.sc, D = G.deed;
D('has_mirror','You carry the Mirror-Shield of Saint Elowen.'); D('sphinx_angry','You angered the Sphinx.'); D('zahra_friend','Queen Zahra of the caravans is your friend.'); D('has_pearl','You carry the Silence Pearl.'); D('sirens_freed','You freed the sirens from the fisherman\'s net.');
D('brannoch_friend','Captain Brannoch trusts you.'); D('has_dawnbreaker','You carry Dawnbreaker, the sunsteel blade.'); D('yeti_friend','The yeti matriarch spared you.'); D('knows_backstory','You know why the Ashen Queen burned Aurelon.'); D('jarl_spared','You spared Jarl Skarn.');
D('ally_lost_sand','A companion was lost to the sandstorm.'); D('has_beeswax','You are prepared against the Sirens\' song.'); D('wyrm_slain','You slew the Great Sandwyrm.'); D('kraken_slain','You slew the Kraken.');

const F = G.foes;
F.f_wyrm = { id:'f_wyrm', n:'The Great Sandwyrm', icon:'🪱', art:'desert|🪱', lv:14, boss:true, weak:['frost','bolt'],
  intro:'The dune ahead heaves, splits, and a column of ringed, armoured flesh the width of a house rises out of the sand, its mouth a pit of teeth. The Great Sandwyrm has woken, and it is hungry.',
  winText:'The wyrm thrashes, shudders, and collapses in a long, rolling wave of sand. The desert falls silent.', win:'xp+l gold+l loot loot flag:wyrm_slain', verbs:['bites','smashes','coils round'],
  sp:[{every:4,text:'The wyrm dives beneath the sand and erupts beneath the Company with a roar!',dmg:1.7},{every:3,text:'It spits a spray of corrosive sand!',dmg:1.0,x:'st:poison2'}] };
F.f_tomb_shade = { id:'f_tomb_shade', n:'Shade of the Tomb-Warden', icon:'👻', art:'dungeon|👻', lv:13, weak:['holy'], undead:true, intro:'A shimmering warrior-shade drifts from the wall, spear lowered. "None take the Saint\'s Shield by force."', winText:'The shade bows, deep and slow, and fades. "Worthy," it breathes.', win:'xp+l', verbs:['stabs','pierces','slashes'] };
F.f_pirates = { id:'f_pirates', n:'Redtide\'s Raiders', icon:'🏴‍☠️', art:'sea|🏴‍☠️', lv:14, intro:'Grappling-hooks bite the gunwale. A dozen pirates swarm aboard, cutlasses flashing, shrieking.', winText:'The last pirate goes over the side with a splash and a curse.', win:'xp+l gold+l loot', verbs:['slashes','hacks','stabs'] };
F.f_kraken = { id:'f_kraken', n:'The Kraken', icon:'🐙', art:'sea|🐙', lv:17, boss:true, weak:['bolt'],
  intro:'The sea goes black, then white, then BOILS. A tentacle thick as a ship\'s mast rises, then another, then a dozen, then something vast and mottled lifts out of the waves, a single enormous eye rolling toward the ship. The Kraken has woken.',
  winText:'The Kraken shudders, releases the ship, and slides beneath the waves. The sea goes quiet, then calm.', win:'xp+l gold+l loot loot flag:kraken_slain', verbs:['crushes','lashes','slams'],
  sp:[{every:3,text:'A tentacle coils round the mast and wrenches the ship sideways!',dmg:1.6},{every:5,text:'The Kraken exhales a cloud of ink and hurls itself against the hull!',dmg:2.0}] };
F.f_siren_queen = { id:'f_siren_queen', n:'The Siren-Queen', icon:'🧜‍♀️', art:'sea|🧜‍♀️', lv:15, weak:['bolt'], intro:'The Siren-Queen\'s song cracks into a scream. Her hair writhes, her eyes turn black, and her hands become talons.', winText:'The Siren-Queen collapses on the rocks, her voice a thin gasp. The song is over.', win:'xp+l', verbs:['claws','screeches at','lunges at'] };
F.f_jarl = { id:'f_jarl', n:'Jarl Skarn, the Frost Giant', icon:'🧊', art:'snow|🧊', lv:18, boss:true, weak:['fire'],
  intro:'A giant in a cloak of wolf-pelts and ice strides down the glacier, axe of frozen steel on his shoulder. "SKARN is Jarl of the Frostmere. SKARN says: turn back, little ones, or become snow."',
  winText:'Jarl Skarn crashes onto the glacier, shaking the ice for a mile. A grave silence, then a low, rumbling laugh. "Good fight," he rumbles, and does not rise again.', win:'xp+l gold+l loot loot', verbs:['chops','hammers','kicks'],
  sp:[{every:3,text:'The Jarl roars; the ice splits beneath you in a spray of frost!',dmg:1.6,x:'st:curse2'}] };
F.f_temple_knight = { id:'f_temple_knight', n:'The Dawn-Knight', icon:'🗡️', art:'snow|🗡️', lv:16, weak:['fire','holy'], undead:true, intro:'The great statue steps down from the plinth, rime cracking from its limbs. "Prove yourself," it says, in a voice like a bell.', winText:'The Dawn-Knight kneels, and offers up its sword hilt-first. "Worthy."', win:'xp+l', verbs:['cleaves','slashes','sweeps'] };

/* ================= CHAPTER VII — THE AMBER WASTES ================= */
G.chapter('r4',{ n:'VII. The Amber Wastes', sub:'Sand, glass and the tomb of a saint', ch:4, region:'amber', art:'desert|🏜️ 🐪', age:20,
  text:`Beyond the swamp lies the desert: the Amber Wastes, a sea of sand and salt-flats and wind-carved stone, where the days are furnaces and the nights are knives. Caravans cross it in the cool months, camel by camel, following wells and a thousand years of tradition. The Company has no camels, no wells, and a map that stops at the edge of the page.\nSomewhere in the dunes lies the tomb of Saint Elowen, the first Lantern-keeper, and the Mirror-Shield that is said to turn any spell back upon its caster. Aldric says the Wastes are a test of patience. Ysolde says they are a test of sunscreen.`,
  beats:()=>G.mix(['r4_caravan','r4_oasis','r4_nomads','r4_sphinx','r4_sandstorm','r4_tomb1','r4_tomb2','r4_tomb3','r4_wyrm','r4_end'],33) });

sc('r4_caravan','desert|🐪 🏜️',
`The first sign of life in a week is a plume of dust on the horizon. A caravan: sixty camels, a hundred drivers, and a gaudy tent on the back of a monstrous white beast. Under the tent sits Queen Zahra of the Sixty Camels, ruler of the trade-roads, with rings on every finger and a smile like a sharpened coin.\n"Lantern-folk!" she cries. "Travellers! My friends! Water, shade, and a very fair price. What do you need?"`,[
 {t:`Ask for water and a place in the caravan.`,y:[`"Of course!" Zahra claps. "A hundred gold for the lot, or a favour." A shrewd glance. "I've a small problem. A very small problem. With sand-bandits."`,'xp+m >r4_zahra_deal']},
 {t:`Offer to guard the caravan in exchange for passage.`,c:'STR 13 fight',y:[`Three days of watching, one skirmish with sand-raiders, and the Queen is delighted. "Wonderful! Marvellous! You may ride free. And here: a little something."`,'xp+l gold+l flag:zahra_friend loot:trink'],n:[`The raiders get past you. The caravan loses some goods. Zahra is disappointed but gracious.`,'xp+m hp-m']},
 {t:`Trade: sell her your odd trinkets.`,r:'any:gimmick',y:[`Zahra clutches a bizarre curio to her chest. "Fascinating!" She pays in gold, and a bag of dried dates.`,'gold+l +ration xp+m']},
 {t:`Politely decline. You'll manage.`,y:[`"Pride," Zahra tuts. "The sand has killed prouder." But she sends a boy with a waterskin anyway.`,'xp+m +ration']} ]);
sc('r4_zahra_deal','desert|🐪 👸',`"Sand-bandits," says Queen Zahra, spreading her hands. "They've been stealing my water-mules. A Lantern-company, a few swords, a bit of ambush... Nothing fancy. I would pay."`,[
 {t:`Set a trap and ambush the bandits.`,c:'INT 13 survive',y:[`A tethered mule, a hidden ditch, a dozen bandits in a very surprised heap. Zahra weeps, cackling. "You are *wonderful*." She presses a heavy purse on you.`,'xp+l gold+l flag:zahra_friend'],n:[`The trap works, mostly. A few bandits flee with a few mules.`,'xp+m gold+s']},
 {t:`Negotiate with the bandits.`,c:'CHA 13 persuade',y:[`You find the bandit camp, and the bandit chief, a tired woman with a broken lute, and strike a deal. Zahra pays a "tax"; the bandits stop. Everybody's grumpy and nobody's dead.`,'xp+l flag:zahra_friend flag:kind gold+m'],n:[`The bandits aren't interested in a deal.`,'hp-m xp+m']},
 {t:`Pay the hundred gold and be done.`,r:'gold:100',y:[`Zahra counts it with practised fingers. "A wise choice. A boring one, but wise."`,'gold-l xp+m']},
 {t:`Decline and strike out alone.`,y:[`"The sand will eat you," says Zahra cheerfully. "But go with my blessing."`,'xp+m']} ]);

sc('r4_oasis','desert|🌴 💧',
`A palm-fringed oasis shimmers on the horizon: green fronds, blue water, a tiny white-domed shrine. After five days of dust, it looks like paradise. The Company staggers toward it, dry-lipped. Even Aldric is walking faster than usual.\nTamsin stops. She puts her hand on your arm. "Wait," she says. "The birds aren't singing."`,[
 {t:`Test the water before drinking.`,r:'skill:survival|skill:herbalism|skill:alchemy|skill:detect|ally:tamsin',c:'WIS 13 survive',y:[`A drop on the tongue: bitter, metallic, wrong. The water is poisoned, and the "shrine" is a bandit's lure. The Company circles wide and finds a clean well in a dry gully.`,'xp+l bond:tamsin'],n:[`You can't tell. The water *seems* fine.`,'xp+m']},
 {t:`Drink anyway. Everyone's dying of thirst.`,c:'CON 13 endure',y:[`The water is cold and sweet and (miraculously) harmless. The Company drinks, and sighs.`,'xp+l hp+l'],n:[`The water is brackish and foul. You throw up in a palm tree.`,'hp-l st:poison4 xp+s']},
 {t:`Scout the shrine first.`,c:'DEX 13 sneak',y:[`In the shrine's shadow, a bandit sleeps. A second wakes, and you strike. The oasis is cleared, and the water is good. The Company drinks gratefully.`,'xp+l loot gold+m'],n:[`The bandits are waiting. Steel flashes.`,'hp-l xp+m gold+s']},
 {t:`Cast a spell to purify the water.`,r:'skill:mending|skill:bless|skill:dispel|skill:frost',mp:3,y:[`A ripple of cool light passes over the pool, and a faint black scum rises, dissolving. The water is clear. The Company drinks, and rests.`,'xp+l rest']},
 {t:`Skirt the oasis and press on with what water you have.`,y:[`A cruel, dry march. By dusk, you find a hidden well in a dry wadi — salty, but drinkable.`,'hp-3 xp+m'],k:1} ]);

sc('r4_nomads','desert|⛺ 🔥',
`A clan of the Sand-Walkers has pitched camp in a hollow between dunes: black tents, copper kettles, children running barefoot. Their elder, a grey woman with a tattooed chin, rises as you approach and lifts both hands. "Travellers," she says. "Sit. In the sand, we do not ask questions before tea."\nThe tea is poured by a boy of eight with great solemnity. Everyone watches to see what you will do.`,[
 {t:`Drink the tea with both hands and say "May your wells never fail."`,y:[`A ripple of approval. The elder smiles. "Someone has taught you manners." After tea, she tells you where the Saint's tomb lies, and that the Wastes have a sphinx.`,'xp+l hp+m flag:heard_sphinx']},
 {t:`Drink and ask about the desert's dangers.`,y:[`"Sandstorms in the next week," she says. "A great worm, as old as the dunes. And the Sphinx, who asks questions." She presses a bundle of herbs into your hand.`,'xp+l hp+s +antidote']},
 {t:`Offer the children a song or a trick.`,r:'skill:music|skill:pickpocket|cls:bard|cls:rogue',y:[`The children shriek with delight. The elder watches, eyes bright. "That," she says, "is the best gift you could give." She gives a fine amulet in return.`,'xp+l loot:trink flag:kind']},
 {t:`Decline politely. You've no time.`,y:[`The elder nods, unoffended. "The sand has its own time." Still, she leaves a skin of water at your side.`,'xp+m +ration']} ]);

sc('r4_sphinx','desert|🦁 🏛️',
`A canyon of red rock closes around the road, and at its narrowest, a vast shape lies across the way: a sphinx of living stone, golden-furred, lion-bodied, with a woman's face and eyes like old copper. She stretches and yawns, showing very long teeth.\n"Travellers," she purrs. "Three questions, and you may pass. Wrong, and I eat. It is very simple. Are you ready?"\nGarrick whimpers. Mira, behind you, is quietly considering the alternative route.`,[
 {t:`"Ask your first question."`,y:[`"What has roots as nobody sees, is taller than trees, up, up it goes, and yet never grows?" She grins, and waits.`,'xp+m >r4_sphinx_q1']},
 {t:`Try to talk your way past.`,c:'CHA 14 persuade',y:[`She laughs, delighted. "Oh, a clever one!" She waves a paw. "I'll let you pass for a favour. Tell me a joke I haven't heard." You tell her the one about the goose. She *roars*.`,'xp+l flag:sphinx_friend'],n:[`"No." The sphinx's amusement vanishes. "Questions first."`,'flag:sphinx_angry >r4_sphinx_q1']},
 {t:`Sneak past while she yawns.`,c:'DEX 15 sneak',y:[`A paw-length at a time. You ease past her great flank, and the Company creeps behind. She snores. You breathe again.`,'xp+l'],n:[`A single huge eye opens. "Mmm," says the sphinx. "*Questions*."`,'flag:sphinx_angry >r4_sphinx_q1']},
 {t:`Find another route, even if it takes a week.`,y:[`A long, dry, labyrinthine detour round the canyon. A week of heat, but nobody gets eaten.`,'xp+m hp-m']} ]);
sc('r4_sphinx_q1','desert|🦁 🧩',`"What has roots as nobody sees, is taller than trees, up, up it goes, and yet never grows?"`,[
 {t:`"A mountain."`,y:[`"Correct." The sphinx's eyes narrow. "Hmm." She tilts her head. "Second question."`,'xp+m quiz+ >r4_sphinx_q2']},
 {t:`"A tall tree."`,y:[`"Wrong, but not by much." A paw swipes, razor claws grazing your arm. "Second question."`,'xp+s quiz- flag:sphinx_angry >r4_sphinx_q2']},
 {t:`"The wind."`,y:[`"Wrong." A paw swipes, and you are slammed against the rock. "Second question."`,'xp+s quiz- flag:sphinx_angry >r4_sphinx_q2']},
 {t:`"I don't know. But I'll find out."`,y:[`"Honest." The sphinx tilts her head. "A cheap answer, but a true one. Second question."`,'xp+m flag:sphinx_angry >r4_sphinx_q2']} ]);
sc('r4_sphinx_q2','desert|🦁 🧩',`"Alive without breath, as cold as death; never thirsty, ever drinking; all in mail, never clinking. What am I?"`,[
 {t:`"A fish."`,y:[`"Correct." The sphinx's tail twitches. "Third question."`,'xp+m quiz+ >r4_sphinx_q3']},
 {t:`"A knight in armour."`,hide:true,r:'!flag:sphinx_angry',y:[`"Wrong." A paw knocks you flat, but you roll aside. "Third question."`,'xp+s quiz- flag:sphinx_angry >r4_sphinx_q3']},
 {t:`"A knight in armour."`,hide:true,r:'flag:sphinx_angry',y:[`"Wrong, wrong, WRONG." The sphinx's jaws open, and her roar flattens you against the rock. Ears ringing, you are shaken but unharmed. "Third question."`,'hp-l xp+s quiz- >r4_sphinx_q3']},
 {t:`"A ghost."`,hide:true,r:'!flag:sphinx_angry',y:[`"Wrong." A swat. "Third question."`,'xp+s quiz- flag:sphinx_angry >r4_sphinx_q3']},
 {t:`"A ghost."`,hide:true,r:'flag:sphinx_angry',y:[`"Wrong." The sphinx pounces and pins you flat with one great paw, thinks better of it and lets go. "Third question."`,'hp-l xp+s quiz- >r4_sphinx_q3']},
 {t:`Ask for a hint.`,hide:true,r:'!flag:sphinx_hint',c:'CHA 13 persuade',y:[`"Hmph." The sphinx sniffs. "It swims." A slow wink. "Answer."`,'xp+m flag:sphinx_hint >r4_sphinx_q2'],n:[`"No hints." A swipe.`,'xp+s quiz- flag:sphinx_angry flag:sphinx_hint >r4_sphinx_q2']},
 {t:`Admit you cannot answer, and bow your head.`,y:[`"Honest," says the sphinx, sniffing. A paw taps you, not unkindly. "Third question."`,'hp-1 flag:sphinx_angry >r4_sphinx_q3']} ]);
sc('r4_sphinx_q3','desert|🦁 🧩',`"Last, and I think hardest. I hold the dead, the living and the not yet born. I have no end and no beginning. Every one of you will leave me, but none can stay. What am I?"`,[
 {t:`"Time."`,y:[`A long silence. The sphinx's copper eyes soften. "Time," she says, quietly. "Yes." She stands, stretches, and steps aside. "Go. And take this, for I have not been asked a good question in a thousand years."`,'xp+xl loot:trink flag:sphinx_friend quiz+'.replace('xp+xl','xp+l')]},
 {t:`"Memory."`,hide:true,r:'!flag:sphinx_angry',y:[`"Almost." The sphinx tilts her head. "Almost is not enough. But you amuse me. Go." She wafts a paw.`,'xp+l hp-s']},
 {t:`"Memory."`,hide:true,r:'flag:sphinx_angry',y:[`"Almost," says the sphinx. "But I am hungry." She pins you flat with one paw, sniffs, and sighs. "...Go."`,'hp-l xp+s quiz-']},
 {t:`"Death."`,hide:true,r:'!flag:sphinx_angry',y:[`"Wrong." She swipes. "But you've had two right, and I'm bored. Go."`,'hp-l xp+m']},
 {t:`"Death."`,hide:true,r:'flag:sphinx_angry',y:[`"Wrong. Oh, so wrong." A paw the size of a cartwheel pushes you across the sand. "Go, before I change my mind."`,'hp-l xp+s quiz-']},
 {t:`Admit defeat and ask for mercy.`,y:[`"Hm." The sphinx studies you. "A coward's answer — but a living one." A lazy paw sweeps you aside. "Go."`,'hp-2 xp+s']},
 {t:`"Love."`,hide:true,r:'!flag:sphinx_angry',y:[`A pause. The sphinx's eyes widen. "No," she says, softly. "But..." Her voice trails. "Go. I will think about that for a century."`,'xp+l hp-s']},
 {t:`"Love."`,hide:true,r:'flag:sphinx_angry',y:[`"Wrong," says the sphinx. But she doesn't pounce. She sits very still, and a tear runs down her golden cheek. "Go," she says. "Before I change my mind."`,'xp+l hp-m']} ]);

sc('r4_sandstorm','desert|🌪️ 🏜️',
`It begins as a brown smudge on the horizon, and within minutes the sky is gone. The wind comes screaming across the dunes, flinging sand like grapeshot. The Company drops, hands over faces, tied together by rope. You can barely hear Aldric over the roar: "HOLD THE LINE! HOLD ON!"\nThen the rope snaps. Two of your companions are swept away: Mira and Ysolde, in opposite directions.`,[
 {t:`Go after Mira.`,r:'ally:mira',c:'DEX 14 dodge',y:[`You fling yourself into the roaring dark, find her half-buried, and drag her up. You crawl back by luck and instinct. Mira, spitting sand, hugs you fiercely.`,'xp+l bond:mira'],n:[`You can't find her. When the storm dies, you find her, alive, but the world has changed.`,'hp-l xp+m flag:mira_shaken']},
 {t:`Go after Ysolde.`,r:'ally:ysolde',c:'DEX 14 dodge',y:[`You find her cursing in a pocket of sand. She grabs your arm. "I'm furious," she says, trembling. "Thank you."`,'xp+l bond:ysolde'],n:[`You can't find her.`,'hp-l xp+m flag:ysolde_shaken']},
 {t:`Cast a ward to hold the Company together.`,r:'skill:ward|skill:shield',mp:3,y:[`A shimmering dome. The storm hammers at it, and fails. When it passes, everyone is accounted for. Aldric stares at you. "That's a thing," he says.`,'xp+xl bond:aldric bond:mira bond:ysolde'.replace('xp+xl','xp+l')]},
 {t:`Hold the line and keep everyone you can.`,c:'STR 14 endure',y:[`You dig in, and hold. Aldric and Osric hold beside you. The storm tears at everyone, but when it passes, everyone is alive. You are scoured raw.`,'hp-m xp+l bond:aldric'],n:[`The line snaps. Mira is swept away, and the Company finds her three days later, half-dead, and furious.`,'hp-l xp+m drop:mira flag:ally_lost_sand flag:mira_left']},
 {t:`Cover your face, lie flat, and tie the Company close.`,y:[`You hug the sand, ropes knotted, praying to every god you've heard of. When the storm passes, everyone is accounted for — scoured raw, but alive.`,'hp-3 xp+m'],k:1} ]);

sc('r4_tomb1','ruins|🏺 🪲',
`Saint Elowen's tomb is carved into a red cliff at the end of a dry canyon: a plain doorway, a stair of sandstone, and a corridor lined with painted scarabs, their eyes inlaid with jet. A plaque in Old Aurelian: "She who bears the light in dark places rests here. Let the unworthy turn back."\nThe first hall is a long colonnade. Hieroglyphs warn of 'the Swarm of the Thief.' A tripwire glints in the dust.`,[
 {t:`Disarm the trap carefully.`,r:'skill:lockpick|ally:mira|cls:rogue',c:'DEX 14 lock',y:[`Click, a hairline wire, a clever little catch. The scarab-jets stay silent. You pass in safety.`,'xp+l'],n:[`A shower of scarabs bursts from the walls, buzzing and biting.`,'hp-l st:poison3 xp+m']},
 {t:`Read the glyphs for the safe path.`,r:'skill:lore|skill:detect|item:scholars_spectacles|ally:ysolde',c:'INT 14 lore',y:[`The glyphs are a map: step on the third, fifth and ninth tile only. You pass, tile by tile, as the scarabs watch.`,'xp+l'],n:[`You misread. A tile sinks. A hiss, a rain of beetles.`,'hp-m xp+m']},
 {t:`Burn the scarabs with fire first.`,r:'skill:firebolt|item:fire_oil|item:torch',y:[`A wall of flame sweeps the hall. The scarabs crackle, and the walls scorch. You pass through smoking corridors.`,'xp+m -fire_oil']},
 {t:`Run for it.`,c:'DEX 15 dodge',y:[`A breathless sprint. The tripwire snaps behind you. Scarabs swarm — and you're through.`,'xp+l'],n:[`A scarab-cloud engulfs you. You stagger out, bitten and poisoned.`,'hp-l st:poison4 xp+m']},
 {t:`Go back and look for the tomb's other entrance.`,y:[`A circuit of the cliff and a bit of luck: a fissure behind a rock, wide enough to squeeze through. It lets you into the second hall.`,'hp-2 xp+m'],k:1} ]);
sc('r4_tomb2','ruins|⏳ 🏺',
`The second hall is a round chamber with a floor of sand, and from the ceiling hang a thousand glass hourglasses, each trickling, each slightly out of sync. A plinth in the centre bears a plaque: "WHICH HOUR IS THE SAINT'S?" On the walls, a hundred doors, all identical.\nSomewhere, very faintly, a bell tolls.`,[
 {t:`Study the hourglasses.`,c:'INT 14 lore',y:[`Out of a thousand, one has a faint lantern-shape in its sand. You point. A single door glows, and swings open on a corridor of warm light.`,'xp+l'],n:[`The glasses blur. You choose a door at random: a long, dusty dead-end.`,'hp-s xp+m']},
 {t:`Follow the bell.`,c:'WIS 14 survive',y:[`A tolling, soft, off to the right. You trust your ears and find a small door, with a single glowing hourglass over it. It swings open.`,'xp+l'],n:[`The bell echoes from everywhere. You wander for an hour.`,'hp-s xp+m']},
 {t:`Break the hourglasses.`,y:[`Glass everywhere, a hissing river of sand. A hidden door springs open — and so does a hidden trap.`,'hp-m xp+m']},
 {t:`Cast Detect Magic.`,r:'skill:detect',mp:1,y:[`A single hourglass glimmers with the warm silver of a saint's blessing. The door beneath it opens at your touch.`,'xp+l']} ]);
sc('r4_tomb3','ruins|🪞 ✨',
`The last chamber is small and bare, lit by a single shaft of sunlight from a hole in the roof. A stone sarcophagus lies in the centre, carved with a woman's serene face. Above it, on the wall, hangs a round shield of polished silver, so bright it hurts to look at. Every surface in the room is mirror-bright, and your reflection, repeated a hundred times, stares back at you.\nA soft voice, like wind through a bell: "Who comes to the Saint?"`,[
 {t:`"A seeker. I come in humility."`,y:[`The light brightens. "Humility," says the voice. "Rare. Welcome." The shield lifts from the wall, and settles on your arm: light as a breath, strong as a mountain.`,'xp+xl +mirror_shield flag:has_mirror'.replace('xp+xl','xp+l')]},
 {t:`"I come for the Mirror-Shield. The world needs it."`,y:[`"The world always does," says the voice, a little wearily. "Take it. But know it will show you yourself." The shield drops into your hands, cool as a lake.`,'xp+l +mirror_shield flag:has_mirror']},
 {t:`Grab the shield and go.`,c:'DEX 14 steal',y:[`The shield is yours. A cold rush, a faint scream, and the walls shake. Something very angry stirs.`,'xp+m +mirror_shield flag:has_mirror battle:f_tomb_shade'],n:[`A spear of light pins your hand to the wall. The shade rises.`,'hp-m battle:f_tomb_shade']},
 {t:`Leave the shield. It belongs here.`,y:[`The light dims, softens. "A good answer," murmurs the voice. "Take it anyway. I'd rather give than be stolen from." The shield settles on your arm.`,'xp+xl +mirror_shield flag:has_mirror flag:kind'.replace('xp+xl','xp+l')]} ]);

sc('r4_wyrm','desert|🪱 🌋',
`A day's march from the tomb, the sand begins to tremble. A low rumble rolls beneath your feet. Tamsin stops, and puts her ear to the ground. "Something big," she whispers. "Under us."\nThe dune ahead heaves.`,[
 {t:`Fight it head-on.`,y:[`The wyrm bursts from the sand, jaws wide. Aldric roars, the Company forms up, and the desert shakes.`,'battle:f_wyrm']},
 {t:`Reflect its spit with the Mirror-Shield.`,r:'item:mirror_shield',y:[`You raise the shield. The wyrm's corrosive spray hits the polished surface, and rebounds. It shrieks, thrashing in its own acid, and the fight begins on your terms.`,'xp+l st:bless3 battle:f_wyrm']},
 {t:`Run for a stony outcrop.`,c:'DEX 14 dodge',y:[`The Company scatters across the sand. The wyrm lurches after Aldric, while Mira and Tamsin sneak round. When it turns, a dozen arrows meet it.`,'xp+l battle:f_wyrm'],n:[`The sand is soft. The wyrm is fast.`,'hp-l battle:f_wyrm']},
 {t:`Lure it away with a noise.`,r:'item:smoke_pellet|item:fire_oil|skill:firebolt',c:'INT 13 survive',y:[`A flash and a bang in the distance. The wyrm turns, dives, and is gone beneath the dunes.`,'xp+l'],n:[`It isn't fooled.`,'battle:f_wyrm']},
 {t:`Bury yourselves in the sand and wait it out.`,y:[`The wyrm snakes past just under the dune, a long, rolling ridge, and slowly its rumble recedes. When you dig out, the wastes are empty.`,'hp-3 xp+m'],k:1} ]);

sc('r4_end','desert|🌅 🌊',
`The Wastes end at a line of white cliffs, and beyond them, a long grey glimmer: the sea. The wind turns damp. Gulls wheel overhead, screaming. The Company limps down a dry riverbed toward the distant lights of a port.\n{?flag:has_mirror|The Mirror-Shield gleams on your back, catching the last of the sun.|}{?flag:ally_lost_sand|Mira's absence is a cold place at the fire.|}\nAldric looks at the sea for a long time. "Ships," he says, finally. "We hate ships." Garrick groans.`,[
 {t:`Say, "I rather like the sea."`,y:[`Aldric turns to you with a sceptical grin. "You haven't been on one." You'll find out. The Company laughs.`,'xp+l bond:aldric']},
 {t:`Check everyone's water and rations.`,y:[`A grim tally. Low. But the port will fix it.`,'xp+l +ration +ration']},
 {t:`Tend to the wounded.`,r:'skill:mending|skill:herbalism|cls:cleric|ally:osric',y:[`You work till dusk. Osric hums. By evening, the Company is in better shape than it has been in a month.`,'xp+l rest bond:osric']},
 {t:`Rest on the beach and look at the stars.`,y:[`A cold, quiet night. The sea whispers. You think of Thornwick, of Wren, and of the ruin of Aurelon. The stars are the same.`,'xp+m hp+m mp+m']} ]);

/* ================= CHAPTER VIII — THE SALTWIND COAST ================= */
G.chapter('r5',{ n:'VIII. The Saltwind Coast', sub:'Harbours, pirates and a song that kills', ch:5, region:'saltwind', art:'coast|⚓ 🌊', age:20,
  text:`The Saltwind Coast is a rim of cliffs and coves, harbour towns and wreckers' lights, and a wind that never stops. The only quick way north is by sea, across the Gulf of Sorrows, past the Isle of the Sirens, to the shores of the Frostmere. The sailors say the gulf has a mind of its own. They say a Kraken sleeps beneath it.\nThe Sage said a pearl lies in the sirens' grotto: the Silence Pearl, which stills any voice within ten paces. If the Ashen Queen's power is in her spells, a pearl of silence might be worth a ship.`,
  beats:()=>G.mix(['r5_calder','r5_tavern','r5_brannoch','r5_pirates','r5_shanty','r5_storm','r5_isle','r5_grotto','r5_kraken','r5_end'],34) });

sc('r5_calder','town|⚓ 🏙️',
`Calder is a port of tarred timber and rope-ladders, built on the water's edge and half on stilts. Ships of every size crowd the quays, flags flying, sailors shouting in a dozen dialects. The smell is fish, tar and money. Mira takes it all in, and visibly relaxes. "Finally," she says. "A place with *crime*."\nAldric hands you a purse. "Supplies. A ship. Whatever the Company needs. You're our quartermaster, for the duration."`,[
 {t:`Hire a ship at the harbourmaster's office.`,c:'CHA 12 persuade',y:[`The harbourmaster, a heavy woman with an eyepatch, points you to the *Gull's Daughter*. "Captain Brannoch's yours, if the price is right." You settle on a fair one.`,'xp+l gold-m'],n:[`She names a ruinous price. You haggle her down to a merely terrible one.`,'gold-l xp+m']},
 {t:`Visit the chandlers for supplies.`,y:[`Rope, rations, tar, beeswax by the pound. A shopkeeper tells you, kindly, "For the Sirens, lad. Stop your ears." You buy a pack, and a good deal else.`,'xp+l +beeswax +beeswax +rope +ration flag:has_beeswax']},
 {t:`Ask the dockside gossips about the Sirens.`,c:'CHA 11 persuade',y:[`An old one-legged sailor tells you: "A Siren sings, and men leap from the deck to drown. Wax in the ears saves you. But the pearl, that's in her grotto. And the Queen of them is mad with grief, they say."`,'xp+l flag:has_beeswax flag:heard_sirens'],n:[`They talk, but you can't tell the true from the tall.`,'xp+m']},
 {t:`Hit the market stalls.`,y:[`Fish, fruit, a man selling lucky stones. You buy a few small, strange things. One of them is lucky.`,'xp+m loot:gimmick loot:cons gold-s']} ]);
sc('r5_tavern','interior|🍺 ⚓',
`The Drowned Rat is the kind of tavern where the chairs are bolted to the floor, and the floor is bolted to the pier. A shanty rattles the rafters. A one-armed barmaid slides you a mug with a look. In the corner, a very large man is beating a very small man at cards, and the small man is winning.\nA grizzled sailor nudges you. "You lot are the Lantern folk, aye? Sailing north? You'll want to meet Captain Brannoch. And you'll want to avoid Redtide."`,[
 {t:`Ask about Redtide.`,y:[`"Pirate queen. Drowned, they say, three years back — and still sailing. Her crew's the dead, and the living who're fool enough to serve. She'll board you. Count on it." He sips. "Don't fight her. Run. Or pay."`,'xp+l flag:knows_redtide']},
 {t:`Buy the sailor a drink and ask for the sea-lore.`,r:'gold:5',c:'CHA 11 persuade',y:[`Two drinks and an hour, and you know: how to read a storm, how to tell a sea-serpent from a log, and how to keep a ship afloat when it wants to sink.`,'xp+l gold-s st:bless4'],n:[`The sailor sinks into his cups and starts crying about his mother.`,'xp+m gold-s']},
 {t:`Join the card game.`,c:'WIS 13 luck',y:[`A few hands, a great deal of poker-face, and you walk away richer by a handful of gold, and a lasting enmity.`,'xp+l gold+l'],n:[`You lose the shirt off your back. Almost.`,'gold-m xp+m']},
 {t:`Pick a fight with the card-shark.`,c:'STR 13 fight',y:[`A bar-brawl of epic proportions. You win. The tavern cheers. A bill arrives.`,'xp+l gold-s'],n:[`You wake in the gutter.`,'hp-l gold-s']} ]);
sc('r5_brannoch','sea|⛵ 👨‍✈️',
`Captain Brannoch of the *Gull's Daughter* is a leathery old man with a crooked nose, a rope of white hair, and a parrot that swears in Aurelian. His ship is a sturdy, ugly, well-patched cog with a crew of a dozen. He looks at your Company, then at the sea, then at you.\n"Lantern folk," he says. "I've carried worse. And better. But I tell you true: the Gulf of Sorrows isn't a place you sail. It's a place you survive."`,[
 {t:`"We'll pay in full. And we'll help work the ship."`,y:[`Brannoch looks at you for a long, long time. Then he grins, showing four teeth. "Aye. I like you." He claps your shoulder. "Climb aboard."`,'xp+l flag:brannoch_friend']},
 {t:`Ask him about the sea ahead.`,y:[`"Pirates, storm and kraken," he says. "In that order. The Siren-isle's on the way, if you're daft enough to land. I'd not. But I'll take you to the cliffs, aye."`,'xp+m']},
 {t:`Ask about the parrot.`,y:[`The parrot says something unprintable in Aurelian. Brannoch beams. "Admiral Fluffy," he says. "Best first mate I've had."`,'xp+m st:bless3']},
 {t:`Offer him a Lantern-pin as pledge.`,r:'item:lantern_pin',y:[`He takes it with great ceremony, holds it to the light, and pins it to his hat. "I'll bring it back," he says gruffly. "You'll want to come get it."`,'xp+l flag:brannoch_friend -lantern_pin']} ]);

sc('r5_pirates','sea|🏴‍☠️ ⚓',
`Three days out, a black sail breaks the horizon, flying a flag that shows a skull with a ruby between its teeth. "Redtide," says Brannoch grimly. "Hold fast, lads. Pray." The pirate ship comes on, fast as a bird, grappling-hooks swinging, every rail lined with grinning faces.\n"Ready the cannon!" shouts Brannoch. "No, wait. We've no cannon."`,[
 {t:`Fight them off.`,y:[`The pirates swarm over the rail, and the Company meets them. Steel on steel, a ring of cutlasses, and shrieks across the deck.`,'battle:f_pirates']},
 {t:`Parley: offer a toll.`,r:'gold:60',c:'CHA 13 persuade',y:[`Redtide's first mate, a woman with a metal jaw, counts the coins, and signals. The pirate ship veers off. You are poorer, but alive.`,'xp+l gold-l'],n:[`"We'll take the lot," she grins, and the pirates board.`,'battle:f_pirates']},
 {t:`Name the Guild of Quiet Hands.`,r:'flag:thieves_ally|flag:redhand_friend',y:[`A pause. The pirate captain squints across the water. "Nim's lot?" She waves. The pirate ship wheels away. "Safe seas, friend."`,'xp+l']},
 {t:`Cast a ward over the ship and sail through.`,r:'skill:ward|skill:frost|skill:lightning',mp:3,c:'INT 13 magic',y:[`A shimmering dome rises, and the pirates' hooks slide off it. The ship strains, wind in the sail, and slips away in a spray of white. Brannoch whoops.`,'xp+l'],n:[`The ward falters. The pirates swarm aboard.`,'battle:f_pirates']},
 {t:`Throw down your arms and let them take the cargo.`,y:[`Redtide's raiders strip the hold, laughing. It costs you dearly, but nobody dies. Brannoch glares at the pirates until they leave.`,'gold-m hp-1 xp+s'],k:1} ]);
sc('r5_shanty','sea|🎶 🌙',
`Night at sea. The ship rocks gently under a sky of stars. The crew, off-watch, have gathered on the foredeck with a keg and a fiddle, singing a shanty so rude that Osric has turned the colour of a boiled beet. Mira's learning the words. Garrick is, to everyone's astonishment, very good at the fiddle.\nBrannoch waves you over. "Come, lad. A song from the Lantern."`,[
 {t:`Sing the Thornwick lullaby.`,c:'CHA 11 perform',y:[`The deck goes quiet. Even the parrot. When you finish, a dozen sailors are wiping their eyes, and Brannoch is blowing his nose like a trumpet.`,'xp+l bond:aldric bond:osric st:bless6'],n:[`You get through two verses before the shanty-singers drown you out. Everyone cheers anyway.`,'xp+m']},
 {t:`Join the shanty.`,y:[`A rousing, filthy, glorious chorus. By the end, you're hoarse and the crew treats you like one of their own.`,'xp+l bond:mira bond:garrick hp+m']},
 {t:`Take the helm for a watch.`,c:'DEX 12 survive',y:[`Under the stars, the ship answers your hands. You steer a straight line north, and Brannoch, watching from the dark, nods once.`,'xp+l flag:brannoch_friend'],n:[`The ship wobbles. Brannoch takes over, gently.`,'xp+m']},
 {t:`Watch the stars with Tamsin.`,r:'ally:tamsin',y:[`She names the constellations, one by one: the Lantern, the Hunter, the Weeping Woman. Her voice is soft. "That one's the Queen's," she says. "It's very bright."`,'xp+l bond:tamsin']} ]);
sc('r5_storm','sea|⛈️ 🌊',
`The storm hits at midnight. A wall of black cloud, a wind like a screaming wolf, waves taller than the mast. The *Gull's Daughter* climbs, hangs, plunges, and the whole ship groans. Brannoch roars orders. Sailors scramble. Water sheets across the deck. A great wave carries away Garrick's fiddle, and Garrick, and drops him thrashing at the rail.\n"MAN OVERBOARD!"`,[
 {t:`Throw a line and haul him back.`,r:'item:rope',c:'STR 13 swim',y:[`The rope flies, and Garrick catches it. A heave, a groan, and he's hauled aboard, spluttering. "My fiddle!" he gasps. "Forget the fiddle," you say.`,'xp+l bond:garrick'],n:[`The rope slips, and the wave takes him. You dive in after.`,'hp-l xp+m bond:garrick']},
 {t:`Dive in after him.`,c:'STR 14 swim',y:[`Cold, black, deafening. You find him by the collar, and a great wave throws you both back onto the deck. Brannoch stares. "Mad," he mutters. "Mad as a gull."`,'xp+l bond:garrick bond:aldric'],n:[`The sea closes over you. You lose track of up and down.`,'hp-l xp+m']},
 {t:`Freeze the sea around him with a spell.`,r:'skill:frost',mp:3,y:[`A shell of ice forms around Garrick, and the Company hauls the whole block aboard. He thaws on the deck, shivering and amazed.`,'xp+l bond:garrick']},
 {t:`Stay at your post. Trust Brannoch.`,y:[`Brannoch swings the ship round, and the sailors catch Garrick as the wave throws him back. You hold the line.`,'xp+m']} ]);

sc('r5_isle','sea|🏝️ 🧜‍♀️',
`The Isle of the Sirens is a spur of black rock rising out of a mist, ringed by white foam. A low, sweet, eerie music drifts across the water. A voice, perhaps a hundred voices, singing without words: a song so lovely that you feel it in your teeth. Several sailors are at the rail already, leaning out, eyes glassy.\n"STOP YOUR EARS!" Brannoch bellows. "ALL HANDS! WAX!"`,[
 {t:`Pack your ears with wax.`,r:'item:beeswax',y:[`The song dwindles to a dull thump. The world goes quiet. Around you, the Company mimes. Mira makes a rude gesture. You laugh, silently.`,'xp+l -beeswax']},
 {t:`Resist the song with your will.`,c:'WIS 14 resist',y:[`The song pulls at your mind like a hook. You grit your teeth, count backwards from a thousand, and hold. The song passes. A few sailors weep.`,'xp+l'],n:[`The song claws into you. You step toward the rail, and Osric tackles you at the last moment.`,'hp-m xp+m']},
 {t:`Sing back, to drown it out.`,r:'skill:music|cls:bard',c:'CHA 14 perform',y:[`You sing, loud and clear, a rough Thornwick sea-song. It cuts the Sirens' music like a knife. The sailors blink, shake themselves, and join in. The Sirens' voices falter.`,'xp+xl st:bless5'.replace('xp+xl','xp+l')],n:[`Your voice breaks. The Sirens' song swells.`,'hp-m xp+m']},
 {t:`Order the ship to sail on. Don't land.`,y:[`Brannoch swings the helm, and the isle recedes, the song fading. You have lost the Pearl, but not the ship.`,'xp+m']} ]);
sc('r5_grotto','cave|🧜‍♀️ 🐚',
`The Sirens' grotto is a cave of pearl-white stone, lit by phosphor and the flicker of waves. In the centre, on a rock like a throne, sits the Siren-Queen: a woman with sea-green hair and skin like moonlight, eyes black as the deep sea, holding something small and glowing in her hands: the Silence Pearl.\nShe is weeping. Around her, a dozen younger sirens lie tangled in a fisherman's net, caught and limp.`,[
 {t:`Cut the sirens free from the net.`,c:'DEX 13 steal',y:[`Knife, rope, and gentle hands. The sirens gasp and shiver, and flee to the water. The Queen watches in silence. At last she holds out the pearl. "Take it," she whispers. "You have shown me something I forgot."`,'xp+xl +silence_pearl flag:has_pearl flag:sirens_freed flag:kind'.replace('xp+xl','xp+l')],n:[`The net is tangled, and the Queen's song slips through your defences. You stumble back, groggy, before you free a few.`,'hp-m xp+l flag:sirens_freed']},
 {t:`Ask for the Pearl, politely.`,c:'CHA 14 persuade',y:[`"A pearl for a pearl," says the Queen. "Give me one of yours." You offer a tear, and she weeps with you. At last, she presses the Silence Pearl into your hand.`,'xp+l +silence_pearl flag:has_pearl'],n:[`"No," says the Queen. "It is the last of my voice."`,'xp+m']},
 {t:`Take the Pearl by force.`,y:[`The Queen's face twists, and her song becomes a scream.`,'battle:f_siren_queen']},
 {t:`Steal the Pearl while the Queen weeps.`,r:'skill:pickpocket|skill:stealth|ally:mira',c:'DEX 15 steal',y:[`A light touch, a soft slide. The Pearl is yours before the Queen blinks. You are out of the grotto before she notices.`,'xp+l +silence_pearl flag:has_pearl'],n:[`The Queen's black eyes snap open.`,'battle:f_siren_queen']} ]);
sc('r5_kraken','sea|🐙 🌊',
`The Gulf of Sorrows lives up to its name. On the fifth night after the Isle, the sea goes flat, then black. A single bubble rises beside the ship. Then another. Brannoch puts down his pipe, very carefully. "Everyone," he says. "To the rail. Weapons. Not a sound."\nThe sea explodes.`,[
 {t:`Fight it.`,y:[`The Kraken's tentacles rise on every side. The ship lurches, and the Company roars.`,'battle:f_kraken']},
 {t:`Hold the Mirror-Shield against its ink-blast.`,r:'item:mirror_shield',y:[`The Kraken's ink-cloud rebounds off the polished shield, blinding the beast. It thrashes, and the Company rushes in.`,'xp+l st:bless4 battle:f_kraken']},
 {t:`Slip the ship away in the dark.`,c:'DEX 15 sneak',y:[`Brannoch, silent as a ghost, swings the helm. The ship slips along the kraken's flank, a breath from the great eye, and out into open water. Nobody breathes for an hour.`,'xp+xl'.replace('xp+xl','xp+l')],n:[`A tentacle brushes the hull. The eye swivels.`,'battle:f_kraken']},
 {t:`Lure it away with fire and noise.`,r:'item:fire_oil|skill:firebolt|skill:lightning',y:[`Fire on the water, a drum of thunder. The Kraken, confused, follows the glow, and the ship creeps off.`,'xp+l -fire_oil']},
 {t:`Heave the cargo overboard as a distraction.`,y:[`Barrels, crates, a whole cart of salted fish. The Kraken seizes the splash, and while it tears the cargo to pieces, the *Gull's Daughter* creeps off.`,'gold-s xp+m'],k:1} ]);
sc('r5_end','coast|🌅 🏔️',
`A white shore at last. The *Gull's Daughter* beaches in a cove of black pebbles, and the Company wades ashore into a cold dawn. The air bites. The ground is hard, and rimed with frost. Ahead, a long, white wilderness of mountains and glaciers: the Frostmere.\nBrannoch stands on the poop deck, one hand on the parrot. "I'll wait," he calls. "Three weeks, then I sail. Come back, if you can."\n{?flag:has_pearl|The Silence Pearl is a quiet weight against your chest.|}`,[
 {t:`Wave to Brannoch.`,y:[`He lifts his hat. The parrot screams a rude farewell. You laugh, a little shakily.`,'xp+l bond:aldric']},
 {t:`Shout back: "We'll be back!"`,y:[`Brannoch grins. "That's the spirit!" His voice carries over the water. You almost believe it.`,'xp+l st:bless5']},
 {t:`Prepare for the cold: warm clothes, tinder.`,y:[`Furs from the ship's stores, a pack of dry kindling, a flask of strong spirits. You'll need all of it.`,'xp+l +torch +torch hp+m']},
 {t:`Say a quiet goodbye to the sea.`,y:[`The sea answers with a long, low murmur. It sounds, you think, like a blessing.`,'xp+m mp+m']} ]);

/* ================= CHAPTER IX — FROSTMERE ================= */
G.chapter('r6',{ n:'IX. The Frostmere Highlands', sub:'A winter that remembers the sun', ch:6, region:'frostmere', art:'snow|❄️ 🏔️', age:21,
  text:`The Frostmere Highlands are the roof of the world: glaciers, ice-caves, long white valleys, and a silence that eats sound. The sun here is a pale coin; the nights last for weeks. The frost-giants of the north rule the passes. The yeti keep the high ridges. And somewhere, in a frozen temple the Aurelian kings once built to the dawn, a sword of living sunlight waits.\nThe Sage's records call it *Dawnbreaker*: a blade forged in the dying heart of a star, the only weapon that has ever scratched the Ashen Queen. Whoever wields it must be worthy. The temple tests that.`,
  beats:()=>G.mix(['r6_blizzard','r6_hearthhold','r6_yeti','r6_bridge','r6_temple','r6_aurora','r6_jarl','r6_end'],35) });

sc('r6_blizzard','snow|🌨️ ❄️',
`The Frostmere welcomes you with a blizzard. Snow comes in sheets, and the cold is a living thing, a knife in the lungs. Visibility is ten feet. Ysolde's lips are blue. Osric has stopped complaining about his knee, which is a very bad sign.\nTamsin points through the white. "A cave," she shouts. "Half a mile. We can make it, if we run."`,[
 {t:`Lead the Company at a hard march.`,c:'CON 14 endure',y:[`Heads down, shoulder to shoulder, you plough through the drifts. The cave appears like a gift from the gods. The Company collapses in its shelter, blue and gasping, alive.`,'xp+l bond:aldric'],n:[`Frostbite nips at your fingers and ears. The Company reaches the cave, but with injuries.`,'hp-l xp+m']},
 {t:`Warm the Company with fire magic.`,r:'skill:firebolt|item:torch|item:fire_oil',y:[`A roaring fire in the heart of the blizzard. The Company huddles round it, and the march continues, steaming.`,'xp+l mp-s hp+m']},
 {t:`Find the cave with Tamsin's guidance.`,r:'ally:tamsin|skill:survival',c:'WIS 13 survive',y:[`Tamsin's eyes, your steady footing. You find the cave without a single wrong turn, and light a fire in minutes.`,'xp+l bond:tamsin'],n:[`You take a wrong turn. It costs an hour.`,'hp-m xp+m']},
 {t:`Dig a snow-shelter.`,c:'STR 13 survive',y:[`Hours of digging, a dozen exhausted soldiers. By midnight, a snug snow-cave; by dawn, the blizzard has passed.`,'xp+l rest'],n:[`The roof collapses. You dig out, filthy and frozen.`,'hp-l xp+m']},
 {t:`Huddle in a drift and share what warmth you have.`,y:[`A white, silent, endless night. In the morning, the blizzard has blown itself out, and the Company is stiff and alive.`,'hp-3 xp+s'],k:1} ]);
sc('r6_hearthhold','village|🏘️ 🔥',
`Hearthhold is the only human settlement in the Frostmere: a ring of turf-roofed longhouses behind a palisade of whalebone, ten miles from the nearest neighbour. A hundred people live here, fur-clad and silent, burning peat for warmth. They watch the Company arrive with a wariness that is almost fear.\nAn elder, a stooped man with a beard of icicles, meets you at the gate. "The ash has come to the north too," he says. "We've nothing. But you may warm yourselves."`,[
 {t:`Share your rations and tell your news.`,y:[`A long night by the peat fire. The villagers thaw, a little. A child sits on your knee. In the morning, they offer sled-dogs and furs.`,'xp+l -ration hp+m flag:kind +shadow_cloak']},
 {t:`Help repair their palisade.`,c:'STR 13 craft',y:[`A morning's hammering, and a grateful village. The elder gives you a pair of warm gloves, and a quiet word: "The temple is north. The giants are east. Don't take the east road."`,'xp+l flag:kind'],n:[`You hit your thumb a lot.`,'hp-s xp+m']},
 {t:`Heal the sick: a fever has taken hold.`,r:'skill:mending|skill:herbalism|ally:osric|cls:cleric',y:[`A week's labour. By the end, a dozen villagers are on their feet, and the village sings you out.`,'xp+l flag:kind bond:osric +healers_kit']},
 {t:`Rest, resupply, and move on.`,y:[`A night's rest, a hot meal, and a pair of snow-shoes. The Company leaves before dawn.`,'xp+m rest']} ]);
sc('r6_yeti','snow|🦍 ❄️',
`On a high ridge, you find a yeti pup caught in a snare, whimpering. It is half your size, shaggy, white, with enormous dark eyes. Its leg is bleeding. You can hear, very faintly, from somewhere beyond the ridge, a deep, rolling roar. The mother, coming.\n"Leave it," says Aldric quietly. "Quickly."`,[
 {t:`Free the pup.`,c:'WIS 12 tame',y:[`The pup lets you cut it free, whimpering. A massive shape rises over the ridge, and you hold up both hands, empty. The matriarch stares at you for a long minute. Then she lifts the pup, and goes. You are spared.`,'xp+xl flag:yeti_friend flag:kind'.replace('xp+xl','xp+l')],n:[`The pup bites you. The matriarch arrives. The fight is on.`,'hp-m battle:elite_fm2']},
 {t:`Soothe it with a song.`,r:'skill:music|cls:bard|skill:beastlore',y:[`A soft, rolling song. The pup quiets, and the great roar outside fades into silence. The matriarch pads close, eyes huge, and watches. She does not attack.`,'xp+l flag:yeti_friend flag:kind']},
 {t:`Leave it. Run.`,y:[`The Company retreats. A roar echoes across the ridge behind you for hours. You are lucky.`,'xp+m flag:callous']},
 {t:`Face the mother and defend your ground.`,y:[`The yeti matriarch rises, enormous, and beats her chest. The glacier cracks.`,'battle:elite_fm2']} ]);
sc('r6_bridge','snow|🌉 🧊',
`A bridge of ice, a hundred feet long, spans a crevasse a thousand feet deep. It is a natural thing, a frozen arch, glittering like a diamond, beautiful, and about as thick as a plate in the middle. The wind howls. The only alternative is a week's detour through giant country.\n"We cross one at a time," says Aldric. "Carefully."`,[
 {t:`Cross first, to test it.`,c:'DEX 14 climb',y:[`Step, step, step. The ice sings under you. You cross in a long, held breath. The Company follows. Not one slip.`,'xp+l bond:aldric'],n:[`The ice cracks. You throw yourself the last ten feet, and land shaking in the snow.`,'hp-l xp+m']},
 {t:`Rope everyone together.`,r:'item:rope',y:[`A line of twelve, rope between each, crossing slow as a funeral. Mira slips; the rope holds. At the far side, nobody speaks for a minute.`,'xp+l']},
 {t:`Freeze the bridge thicker with a spell.`,r:'skill:frost',mp:3,y:[`A shimmer of cold, a creak, a sigh. The bridge doubles in thickness, solid as granite. The Company crosses at a stroll.`,'xp+l']},
 {t:`Take the long detour.`,y:[`A week of giant-country. Cold, long, and strangely peaceful.`,'xp+m hp-2']} ]);

sc('r6_temple','snow|🏛️ ❄️',
`The Temple of the Dawn rises out of a glacier like a tooth: white marble pillars, a dome of blue ice, and a great door of silver-white metal. A frozen statue of a knight stands before it, a sword raised to the sky. Letters are carved on the plinth: "WHOEVER WOULD CARRY THE DAWN MUST BE WILLING TO LET IT BURN."\nThe door is unlocked. It swings inward with a long, bell-like note.`,[
 {t:`Enter, and walk the temple's halls.`,y:[`Inside, the temple is a cathedral of ice and light, white and gold. A hundred statues of knights line the nave. At its end, an altar, and on the altar, a sword.`,'xp+l >r6_temple_t1']},
 {t:`Study the plinth's inscription first.`,r:'skill:lore|skill:detect|item:scholars_spectacles',y:[`Three trials, the carvings say: Courage, Truth, and Sacrifice. Fail any, and the guardian wakes.`,'xp+l flag:knows_temple >r6_temple_t1']},
 {t:`Ask Aldric to lead.`,y:[`Aldric steps forward, and looks around, and shakes his head. "I'm not worthy," he says. "I know it. You go." He steps back.`,'xp+l bond:aldric >r6_temple_t1']},
 {t:`Hold back. Let the Company explore first.`,y:[`Mira scouts ahead. "No traps," she whispers. "Strange. Beautiful. Wrong." She waves you in.`,'xp+m >r6_temple_t1']} ]);
sc('r6_temple_t1','snow|🔥 ❄️',
`The first hall is the Trial of Courage. A long corridor of ice, and at its far end, the altar. Between you and it, a river of pure white fire, flowing along the floor, silent and terrible. A voice, cool and clear, speaks from the walls: "Walk through, and do not flinch."`,[
 {t:`Walk through the flames.`,c:'CON 14 endure',y:[`Fire, white, not hot — *cold*, ferocious, cleansing. It strips something from you, and you step out the other side changed. A statue nods.`,'xp+l hp-m flag:trial_courage >r6_temple_t2'],n:[`You flinch. The fire flares and burns.`,'hp-l xp+m >r6_temple_t2']},
 {t:`Pray for courage.`,r:'skill:bless|skill:mending|cls:cleric',y:[`The flames part like a curtain. You walk through untouched. The voice says nothing, but approves.`,'xp+l flag:trial_courage >r6_temple_t2']},
 {t:`Dispel the flames.`,r:'skill:dispel',mp:5,y:[`The fire vanishes. A statue's head turns, slow, as if impressed — or insulted. The trial passes, though with an odd, unsatisfied feeling.`,'xp+m >r6_temple_t2']},
 {t:`Jump across.`,c:'DEX 15 climb',y:[`A long, graceless leap. You land, rolling, on the far side. The voice: "...Acceptable."`,'xp+l flag:trial_courage >r6_temple_t2'],n:[`You land in the fire. It burns *very* much.`,'hp-l >r6_temple_t2']},
 {t:`Wait quietly until the white fire burns low, then cross.`,y:[`Hours of stillness. The fire gutters, and the voice murmurs: "Patience is also courage." You walk through the embers.`,'xp+s >r6_temple_t2'],k:1} ]);
sc('r6_temple_t2','snow|🪞 ❄️',
`The second hall is the Trial of Truth. A mirror of ice stretches from floor to roof, and in it stands your reflection, not as you look, but as you are. It speaks, in your own voice: "What is the thing you have done that you are most ashamed of?"`,[
 {t:`Tell it the truth.`,y:[`You say it aloud: the thing you have never said to anyone. The mirror trembles, and then, softly, shatters into a thousand falling stars. A weight leaves you.`,'xp+xl flag:trial_truth >r6_temple_t3'.replace('xp+xl','xp+l')]},
 {t:`Refuse to answer.`,c:'WIS 14 resist',y:[`The mirror waits. You hold your silence. At last it cracks, and a voice says: "Pride, then. But honest pride." The trial passes.`,'xp+l >r6_temple_t3'],n:[`The mirror flares. A cold spear of light pierces your chest.`,'hp-l xp+m >r6_temple_t3']},
 {t:`Lie.`,c:'CHA 15 deceive',y:[`The mirror frowns, then, impressed, accepts it. "A good liar," it says. "A dangerous quality, in a hero." The trial passes, barely.`,'xp+m >r6_temple_t3'],n:[`The mirror knows. A shard of ice drives into your shoulder.`,'hp-l >r6_temple_t3']},
 {t:`Say it was the betrayal in Thornwick.`,r:'flag:aldric_betrayed',y:[`The mirror shudders. A sound like a sigh rolls through the hall. "That," it says, "will do." The trial passes, and something in you is eased.`,'xp+l flag:trial_truth >r6_temple_t3']} ]);
sc('r6_temple_t3','snow|🗡️ ❄️',
`The third hall is the Trial of Sacrifice. At its centre, an altar, and a sword upon it, long, gleaming, singing softly: Dawnbreaker. A plaque beneath: "TO CARRY THE DAWN, GIVE UP SOMETHING YOU LOVE."\nThe air shimmers. The statue-knights are watching. A single, empty bowl waits beside the sword.`,[
 {t:`Give up your gold: all of it.`,r:'gold:50',y:[`You pour your coin into the bowl, and the metal sings. The sword lifts from the altar and drops into your hand: light as a feather, warm as a hearth.`,'xp+xl -dawnbreaker_gold +dawnbreaker flag:has_dawnbreaker'.replace('-dawnbreaker_gold','gold-l gold-l gold-l').replace('xp+xl','xp+l')]},
 {t:`Give up something precious: your weapon.`,r:'item:steel_sword|item:iron_sword|item:dwarven_axe|item:rapier|item:mace',y:[`You lay down your old weapon, and the sword lifts from the altar. The statue-knights bow, one by one. Dawnbreaker is yours.`,'xp+l +dawnbreaker flag:has_dawnbreaker -iron_sword -steel_sword']},
 {t:`Give up some of your health.`,y:[`You cut your palm, and let the blood fall into the bowl. The metal sings. A faint, bright pain, and the sword is in your hand. It weighs nothing at all.`,'xp+l hp-l maxhp+0 +dawnbreaker flag:has_dawnbreaker']},
 {t:`Refuse to give up anything. Take the sword.`,c:'STR 15 fight',y:[`You grab the hilt, and the sword burns in your hand. The statues turn. But the sword, strangely, doesn't resist. It seems to approve of stubbornness.`,'xp+l +dawnbreaker flag:has_dawnbreaker hp-l'],n:[`A statue steps down from its plinth, sword raised.`,'battle:f_temple_knight']},
 {t:`Kneel, and ask humbly for the sword.`,y:[`You set down your pride, and ask. The statues are silent. Then the sword lifts from the altar, and settles in your hand, light as a breath. "The humble may carry the dawn," says a voice.`,'xp+l hp-2 +dawnbreaker flag:has_dawnbreaker'],k:1} ]);

sc('r6_aurora','snow|🌌 ❄️',
`That night, the sky ignites. Ribbons of green and violet, a hundred miles long, ripple across the Frostmere, brighter than the moon. The Company sits on a ridge in stunned silence. Then, in the swirling light, a shape forms: a woman, vast as a mountain, in a robe of cinders, standing in a tower of black glass.\nThe aurora *shows* you: a village by a river, a child with dark hair, a woman who heals the sick. A fever. A coffin. A woman on her knees, screaming, and fire, and fire.`,[
 {t:`Watch it all, and listen.`,y:[`You see it: Vorathra, healer of Aurelon, her daughter Elaris dead of the fever, her prayers unanswered, and the thing she did: she called the sun down to burn the plague and the fever and the *world* that had taken her child. The tower. The ash. The grief that never ended.`,'xp+xl flag:knows_backstory flag:heard_mother flag:heard_locket'.replace('xp+xl','xp+l')]},
 {t:`Look away. You don't want to see her pain.`,y:[`You close your eyes, and the aurora passes. You carry a shadow of it, though, a feeling of a vast sorrow far away.`,'xp+m flag:heard_mother']},
 {t:`Ask Ysolde what she makes of it.`,r:'ally:ysolde',y:[`Ysolde's face is wet. "She wasn't trying to destroy," she says. "She was trying to *stop it hurting*." She wipes her eyes. "I think it's the worst spell ever cast."`,'xp+l bond:ysolde flag:knows_backstory flag:ysolde_pity']},
 {t:`Reach out toward the light.`,r:'skill:spiritspeak|skill:detect|skill:bless',mp:2,y:[`The aurora bends to your hand, and for a second you stand inside her memory. You feel her grief. You feel her love. You feel the fire. When it passes, you are shaking, and know more than you wished.`,'xp+xl flag:knows_backstory flag:heard_mother flag:heard_locket'.replace('xp+xl','xp+l')]} ]);

sc('r6_jarl','snow|🧊 🏔️',
`The Frost Giants hold the pass to the Ashen Marches: Jarl Skarn and his thirty brothers, each the height of a tower. The Company walks into their hall: an ice-cavern the size of a cathedral, lit by a trench of blue fire. Skarn, a vast figure in a cloak of wolf-pelts, rises from a throne of frozen bone.\n"Humans," he rumbles. "SKARN has sworn: none pass to the north. The Queen's ash is poison; her soldiers have burned three of my brothers. You go there? To die?"`,[
 {t:`"We go to end her. Let us pass."`,c:'CHA 14 persuade',y:[`The Jarl laughs, a rolling thunder. "End her! A handful of little ones!" But he stops. Studies you. "Hm. There is a fire in you." He waves a hand. "Pass. And may the Queen's end be quick."`,'xp+xl flag:jarl_spared'.replace('xp+xl','xp+l')],n:[`"No," says the Jarl. "You will turn back, or you will fight." He lifts his axe.`,'battle:f_jarl']},
 {t:`Challenge him to single combat.`,y:[`The Jarl's eyes gleam. "A duel!" he booms. "SKARN loves a duel." He stamps, and the ice trembles.`,'battle:f_jarl']},
 {t:`Offer the Jarl a gift.`,r:'item:dwarven_axe|item:iron_ration|item:healing_draught|gold:100',y:[`The Jarl takes it, turns it in his enormous fingers, and nods. "A fair tribute. Pass, little ones, with SKARN's blessing."`,'xp+l flag:jarl_spared gold-l']},
 {t:`Use the Dawnbreaker's light to impress him.`,r:'item:dawnbreaker',y:[`You raise the sword, and the hall blazes with white-gold fire. The Jarl staggers back, shielding his eyes. "SUNSTEEL!" he roars. "The old light!" He kneels, awestruck. "Pass, bearer. Pass, and may the dawn rise with you."`,'xp+xl flag:jarl_spared'.replace('xp+xl','xp+l')]},
 {t:`Back out of the hall and take the long pass.`,y:[`A cold, long walk round the Jarl's mountain, with giant footprints in the snow. You are not followed.`,'hp-3 xp+s'],k:1} ]);
sc('r6_end','snow|🌄 🌋',
`The Frostmere falls behind. The glacier slopes away, and beyond it, a vast grey country opens to the northern horizon: the Ashen Marches. The wind changes. It no longer smells of snow; it smells of cold hearths, old smoke, and something faintly sweet.\nBeneath the Marches, the maps say, lies the Hollow Deep: a vast network of caves and underground rivers that crosses beneath the border, the only safe way past the Queen's watchers. The entrance is a crack in the glacier's foot.\nAldric looks at the crack. "Down," he says. "Well. Of course."`,[
 {t:`Say, "I'll go first."`,y:[`Aldric nods once. "Good. I'll be right behind you." He clasps your arm. "Don't die."`,'xp+l bond:aldric']},
 {t:`Ask the Company if everyone's ready.`,y:[`A chorus of nervous yeses. Mira checks her picks. Osric checks his bandages. Garrick checks his boots. Everyone is as ready as they'll ever be.`,'xp+l bond:mira bond:osric']},
 {t:`Rest a moment before the descent.`,y:[`A last hot meal in the sunlight. A last look at the stars. You will not see them again for a long time.`,'xp+l rest']},
 {t:`Write a last letter to Wren.`,y:[`A short one, dated, sealed with wax. You give it to a passing hunter, to carry south. You'll never know if it arrives.`,'xp+l flag:wren_remembers']} ]);
})();
